72	/** Tolerant JSON array read: a corrupt column degrades to an empty list. */
73	export function parseJsonArray<T>(raw: string): readonly T[] {
74	  try {
75	    const parsed: unknown = JSON.parse(raw);
76	    return Array.isArray(parsed) ? (parsed as T[]) : [];
77	  } catch {
78	    return [];
79	  }
80	}
